$ErrorActionPreference = 'Stop'
$root = 'C:\dev\nial_diary'
$mainPath = Join-Path $root 'lib\main.dart'
$pubPath = Join-Path $root 'pubspec.yaml'
$storagePath = Join-Path $root 'lib\services\diary_storage.dart'
$mediaPath = Join-Path $root 'lib\services\nial_media.dart'
if ((Get-FileHash -LiteralPath $mainPath -Algorithm SHA256).Hash -ne 'F5AE5CE5256814BADB4565A6AD6E0C5FB9C034496AD8C90A4A9E99A42139CF50') {
  throw 'main.dart differs from uploaded source or this update is already installed. No changes saved.'
}
if ((Get-FileHash -LiteralPath $storagePath -Algorithm SHA256).Hash -ne 'A59B659C8DFAD9704E88DD2B37DBE19B0803C3C5356B491F7EA32E9E4731A51D') {
  throw 'diary_storage.dart differs from uploaded source. No changes saved.'
}
if (Test-Path -LiteralPath $mediaPath) { throw 'nial_media.dart already exists. No changes saved.' }
$pub = [IO.File]::ReadAllText($pubPath)
foreach ($required in @('record', 'audioplayers', 'file_picker', 'uuid')) {
  if ($pub -notmatch ("(?m)^  " + $required + ':')) {
    throw "Required dependency missing: $required. No changes saved."
  }
}
foreach ($dependency in @('archive', 'path_provider', 'video_player')) {
  if ($pub -match ("(?m)^  " + $dependency + ':')) {
    throw "Dependency already exists: $dependency. Review its version. No changes saved."
  }
}
$rx = [regex]::new('(?m)^  audioplayers:[^\r\n]*')
$hits = $rx.Matches($pub)
if ($hits.Count -ne 1) { throw 'Expected one audioplayers dependency. No changes saved.' }
$hit = $hits[0]
$at = $hit.Index + $hit.Length
$pub = $pub.Substring(0, $at) + "`n  archive: 4.7.1`n  path_provider: 2.1.6`n  video_player: 2.14.1" + $pub.Substring($at)
$encodedMain = @'

'@
$encodedStorage = @'

'@
$encodedMedia = @'

'@
$newMain = [Convert]::FromBase64String($encodedMain.Trim())
$newStorage = [Convert]::FromBase64String($encodedStorage.Trim())
$newMedia = [Convert]::FromBase64String($encodedMedia.Trim())
$backup = Join-Path $root ('backups\before_video_media_' + (Get-Date -Format 'yyyyMMdd_HHmmss_fff'))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Copy-Item -LiteralPath $mainPath -Destination (Join-Path $backup 'main.dart.bak')
Copy-Item -LiteralPath $pubPath -Destination (Join-Path $backup 'pubspec.yaml.bak')
Copy-Item -LiteralPath $storagePath -Destination (Join-Path $backup 'diary_storage.dart.bak')
try {
  [IO.File]::WriteAllBytes($mainPath, $newMain)
  [IO.File]::WriteAllBytes($storagePath, $newStorage)
  [IO.File]::WriteAllBytes($mediaPath, $newMedia)
  [IO.File]::WriteAllText($pubPath, $pub, [Text.UTF8Encoding]::new($false))
} catch {
  Copy-Item -LiteralPath (Join-Path $backup 'main.dart.bak') -Destination $mainPath -Force
  Copy-Item -LiteralPath (Join-Path $backup 'pubspec.yaml.bak') -Destination $pubPath -Force
  Copy-Item -LiteralPath (Join-Path $backup 'diary_storage.dart.bak') -Destination $storagePath -Force
  Remove-Item -LiteralPath $mediaPath -Force -ErrorAction SilentlyContinue
  throw
}
Write-Host 'SUCCESS: video, file-based media and ZIP backups installed.'
Write-Host 'Run flutter pub get, dart format, flutter analyze. Data migration runs on app startup.'
Write-Host "Source backups: $backup"
